import { API_BASE_URL } from "../constants/constants";

// Function to get budget from the backend. Method: GET
export const fetchBudget = async (): Promise<number> => {

    //const response = await fetch(`${API_BASE_URL}/budget`);
    const response = await fetch(`${API_BASE_URL}/budget`, {
        method: "GET"
      });

	if (!response.ok) {
    	throw new Error('Failed to fetch budgets');
	}

    // Parsing the response to get the data
	let data = response.json().then((jsonResponse) => {
    	//console.log("data in fetchBudget", jsonResponse);
    	return jsonResponse.data;
	});

	//console.log("response in fetchBudget", data);
	return data;
};

export const updateBudget = async (budget: number): Promise<number> => {
    const response = await fetch(`${API_BASE_URL}/budget`, {
        method: "PUT",
        headers: {
            "Content-Type": "application/json",
        },
        body: JSON.stringify({ amount: budget }),
      });
    
    if (!response.ok) {
    throw new Error("Failed to update budget");
    }
    //return response.json();

    const data = response.json().then((jsonResponse) => {
        //return jsonResponse.budget;
        return jsonResponse.data;

      });
      return data;
    
};
